CREATE TABLE IF NOT EXISTS public.identity_pair_decisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id text NOT NULL REFERENCES public.organizations(id),person_a_id uuid NOT NULL REFERENCES public.people(id),person_b_id uuid NOT NULL REFERENCES public.people(id),decision text NOT NULL CHECK(decision IN ('not_duplicate','duplicate_merged','duplicate_verified')),decided_by uuid REFERENCES public.users(id),evidence jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(person_a_id<>person_b_id));
CREATE UNIQUE INDEX IF NOT EXISTS identity_pair_decisions_unq ON public.identity_pair_decisions(organization_id,LEAST(person_a_id,person_b_id),GREATEST(person_a_id,person_b_id));
ALTER TABLE public.identity_pair_decisions ENABLE ROW LEVEL SECURITY;
